begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select plan(12);
create temporary table question_fixture as select '[{"id":"10000000-0000-4000-8000-000000000001","label":"Tamanho da camiseta","kind":"select_other","required":true,"options":["P","M","G"]}]'::jsonb q;
select ok(private.event_ticket_questions_valid(q),'lista com outro aceita') from question_fixture;
select ok(private.event_ticket_answers_valid('{"10000000-0000-4000-8000-000000000001":"M"}',q),'tamanho definido aceita') from question_fixture;
select ok(private.event_ticket_answers_valid('{"10000000-0000-4000-8000-000000000001":"Outro: Infantil 8"}',q),'outro informado aceita') from question_fixture;
select ok(not private.event_ticket_answers_valid('{"10000000-0000-4000-8000-000000000001":"Outro: "}',q),'outro vazio recusa') from question_fixture;
select ok(not private.event_ticket_answers_valid('{"10000000-0000-4000-8000-000000000001":"XL"}',q),'opcao arbitraria recusa') from question_fixture;
select ok(not private.event_ticket_answers_valid('{}',q),'obrigatoria ausente recusa') from question_fixture;
select ok(private.event_ticket_answers_valid('{}',jsonb_set(q,'{0,required}','false')),'opcional ausente aceita') from question_fixture;
select ok(not private.event_ticket_questions_valid(jsonb_set(q,'{0,options}','["P","Outro"]')),'opcao reservada recusa') from question_fixture;
select ok(not private.event_ticket_questions_valid(jsonb_set(q,'{0,options}','[]')),'lista vazia recusa') from question_fixture;
select ok(not private.event_ticket_answers_valid('{"10000000-0000-4000-8000-000000000001":"Outro: Infantil 8"}',jsonb_set(q,'{0,kind}','"select"')),'snapshot antigo nao ganha outro') from question_fixture;
select ok(not private.event_ticket_answers_valid('{"forjada":"M"}',q),'pergunta forjada recusa') from question_fixture;
select ok(not private.event_ticket_answers_valid(jsonb_build_object('10000000-0000-4000-8000-000000000001','Outro: '||repeat('a',1000)),q),'resposta excessiva recusa') from question_fixture;
select * from finish();
rollback;
